package com.androlua;

/**
 * Teks antarmuka dalam 50 bahasa (perintah al kautsar 2026-11-23):
 * pemetaan kunci Indonesia -> terjemahan per kode bahasa,
 * dibangkitkan dari berkas teks-<kode>.txt di folder
 * terjemahan-panduan (150 kunci tahap A+B, urutan sama dengan
 * kunci-teks-ui.txt). Kelas murni tanpa Android, bisa diuji
 * di JVM. Kunci yang tidak dikenal, bahasa yang tidak dikenal,
 * atau terjemahan kosong jatuh kembali ke kunci Indonesia
 * itu sendiri, jadi layar tidak pernah menampilkan teks kosong.
 *
 * JANGAN sunting berkas ini dengan tangan — jalankan
 * gen_teksui.py di folder terjemahan-panduan bila ada
 * berkas teks-*.txt yang berubah.
 */
